add_action( 'admin_menu', 'perfectpixel_disable_site_health_menu', 999 );
add_action( 'admin_init', 'perfectpixel_disable_site_health_page' );
add_action( 'wp_dashboard_setup', 'perfectpixel_disable_site_health_widget', 20 );
add_action( 'init', 'perfectpixel_disable_site_health_cron' );

function perfectpixel_disable_site_health_menu() {
	remove_submenu_page( 'tools.php', 'site-health.php' );
}

function perfectpixel_disable_site_health_page() {
	global $pagenow;
	if ( 'site-health.php' === $pagenow ) {
		wp_safe_redirect( admin_url() );
		exit;
	}
}

function perfectpixel_disable_site_health_widget() {
	remove_meta_box( 'dashboard_site_health', 'dashboard', 'normal' );
}

function perfectpixel_disable_site_health_cron() {
	if ( class_exists( 'WP_Site_Health' ) ) {
		remove_action( 'wp_site_health_scheduled_check', array( WP_Site_Health::get_instance(), 'wp_cron_scheduled_check' ) );
	}
}
